    "generatedEnergy": "红色×1",
    "effect": "[自分のターン中]\n[ターン1]\n相手の効果でこのキャラが場を離れる場合、代わりに場を離れない。\n[相手のターン中]\nこのキャラはBP+500。\n[レイド]\n〈切島 鋭児郎〉アクティブにし、フロントLに移動できる\n[自分のターン中]\n[フロントLにある場合]\n自分のフロントLのキャラ全ては、BP+500。自分が「BPの範囲に指定がある効果」でキャラを選ぶ際、指定できるBPの範囲+500。",
    "effectZh": "[自己的回合中]\n[第 1 回合]\n若对方效果使该角色离场，则代替不离开场地。\n[对方的回合中]\n该角色 BP+500。\n[Raid]\n可将〈切岛锐儿郎〉激活并移动至前线 L\n[在前线 L 时]\n自己所有位于前线 L 的角色均为 BP+500。当使用“指定 BP 范围的效果”选择角色时，可指定的 BP 范围 +500。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
    "triggerZh": "[Raid]\n将此卡加入手牌或满足必要能量时发动 Raid。",
