    "effect": "[登場時]\nAPを1支払ってもよい。そうした場合、以下から1つ選ぶ。\n・このキャラをアクティブにし、このキャラはこのターン中、BP+1000。\n・BP3000以下の相手のフロントLのキャラを1枚まで選び、レストにする。それは次の1回アクティブにならない。",
    "effectZh": "[登场时]\n可支付 1 AP。若如此，则从以下选择 1 个。\n·激活该角色，且该角色本回合中 BP+1000。\n·选择对方位于前线 L 的、原本 BP 为 3000 以下的角色至多 1 张并横置。其下 1 次无法被激活。",
