    "effectZh": "【对方回合中】\n【位于前线L时】\n自己选择红色\n【彩色触发器】\n角色时可指定的BP范围+1000。（并非只能选BP2500以下，而是可以选BP3500以下）\n【登场时】\n也可以支付1点AP。若如此做，可选择对方前线L上BP在2500以下的角色最多1枚并使其退场。\n【启动主效果】\n【支付1点AP】\n【回合1】\n本角色在本回合中,\n获得\n【冲击（1）】",
